 const getTimedCaption=(atTime:number)=>{if(!captionChunks.length)return caption;const index=captionChunks.findIndex(part=>atTime>=part.start&&atTime<=part.end);if(index<0)return "";const first=Math.max(0,Math.min(index-2,captionChunks.length-4));return captionChunks.slice(first,Math.min(captionChunks.length,first+4)).map(part=>part.text).join(" ");};
 const downloadSrt=()=>{if(!captionChunks.length){alert("Generate timed captions first.");return;}const stamp=(value:number)=>{const ms=Math.max(0,Math.round(value*1000));const h=Math.floor(ms/3600000);const m=Math.floor(ms%3600000/60000);const s=Math.floor(ms%60000/1000);const milli=ms%1000;return String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0")+","+String(milli).padStart(3,"0");};const groups:{text:string;start:number;end:number}[]=[];for(let i=0;i<captionChunks.length;i+=5){const group=captionChunks.slice(i,i+5);groups.push({text:group.map(part=>part.text).join(" "),start:group[0].start,end:group[group.length-1].end});}const content=groups.map((part,i)=>(i+1)+"\\n"+stamp(part.start)+" --> "+stamp(part.end)+"\\n"+part.text).join("\\n\\n");const url=URL.createObjectURL(new Blob([content],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=(file?.name.replace(/\\.[^.]+$/,"")||"clip")+"-captions.srt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const getAnimatedBox=(kind:"game"|"facecam",atTime:number)=>{const base=kind==="game"?game:facecam;const points=keyframes[kind];if(!points.length)return base;const sorted=[...points].sort((a,b)=>a.time-b.time);if(atTime<=sorted[0].time)return sorted[0];if(atTime>=sorted[sorted.length-1].time)return sorted[sorted.length-1];const index=sorted.findIndex((point,i)=>i<sorted.length-1&&atTime>=point.time&&atTime<=sorted[i+1].time);if(index<0)return base;const a=sorted[index],b=sorted[index+1],t=(atTime-a.time)/Math.max(.001,b.time-a.time);return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,w:a.w+(b.w-a.w)*t,h:a.h+(b.h-a.h)*t};}; const addKeyframe=()=>{const kind=active==="facecam"?"facecam":"game";const box=kind==="facecam"?facecam:game;setKeyframes(previous=>({...previous,[kind]:[...previous[kind].filter(point=>Math.abs(point.time-time)>.05),{time,x:box.x,y:box.y,w:box.w,h:box.h}].sort((a,b)=>a.time-b.time)}));}; const clearKeyframes=()=>setKeyframes(previous=>({...previous,[active==="facecam"?"facecam":"game"]:[]}));
 const addSplit=()=>{const end=trimEnd||duration;if(!duration||time<=trimStart+.05||time>=end-.05)return;setSplitPoints(p=>p.some(point=>Math.abs(point-time)<.08)?p:[...p,time].sort((a,b)=>a-b));};
 const detectSceneCuts=async()=>{const v=videoRef.current;const end=trimEnd||duration;if(!v||!duration||end<=trimStart){alert("Import a video and set a valid trim range first.");return;}const canvas=document.createElement("canvas");canvas.width=32;canvas.height=18;const ctx=canvas.getContext("2d");if(!ctx){alert("Scene detection is unavailable in this browser.");return;}const original=v.currentTime;const cuts:number[]=[];let previous:Uint8ClampedArray|null=null;setDetectingScenes(true);setSceneStatus("Scanning video frames locally…");try{v.pause();setPlaying(false);let count=0;for(let t=trimStart+.75;t<end;t+=1.5){if(Math.abs(v.currentTime-t)>.025){v.currentTime=t;await new Promise<void>(resolve=>v.addEventListener("seeked",()=>resolve(),{once:true}));}ctx.drawImage(v,0,0,32,18);const pixels=ctx.getImageData(0,0,32,18).data;if(previous){let difference=0;for(let i=0;i<pixels.length;i+=4){difference+=(Math.abs(pixels[i]-previous[i])+Math.abs(pixels[i+1]-previous[i+1])+Math.abs(pixels[i+2]-previous[i+2]))/(3*255);}difference/=32*18;if(difference>.28)cuts.push(t);}previous=new Uint8ClampedArray(pixels);count++;if(count%5===0)setSceneStatus("Scanned "+format(t)+" · "+cuts.length+" possible cuts");}setSplitPoints(previous=>{const sorted=[...previous,...cuts].sort((a,b)=>a-b);return sorted.filter((point,index)=>index===0||point-sorted[index-1]>.65);});setSceneStatus("Found "+cuts.length+" possible scene changes · review markers before deleting clips");}catch{setSceneStatus("Scene scan failed. Try a shorter clip or another video format.");}finally{v.currentTime=original;setTime(original);setDetectingScenes(false);}};
 const getTrackedCenter=(atTime:number)=>{if(!faceTrackPoints.length)return{x:.5,y:.5};if(atTime<=faceTrackPoints[0].time)return{x:faceTrackPoints[0].x,y:faceTrackPoints[0].y};if(atTime>=faceTrackPoints[faceTrackPoints.length-1].time){const p=faceTrackPoints[faceTrackPoints.length-1];return{x:p.x,y:p.y};}const index=faceTrackPoints.findIndex((point,i)=>i<faceTrackPoints.length-1&&atTime>=point.time&&atTime<=faceTrackPoints[i+1].time);if(index<0)return{x:.5,y:.5};const a=faceTrackPoints[index],b=faceTrackPoints[index+1],t=(atTime-a.time)/Math.max(.001,b.time-a.time);return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};};
 const analyzeFaceTrack=async()=>{const v=videoRef.current;if(!v||!file?.type.startsWith("video/")||!duration){alert("Import a video before running face tracking.");return;}const original=v.currentTime;const start=Math.max(0,trimStart),end=trimEnd||duration;if(end<=start){alert("Set a valid trim range.");return;}setTrackingFaces(true);setSceneStatus("Loading MediaPipe face tracker…");let landmarker:any;try{const {FilesetResolver,FaceLandmarker}=await import("@mediapipe/tasks-vision");const vision=await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@1.2.3/wasm");const model="https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task";const options:any={baseOptions:{modelAssetPath:model},runningMode:"VIDEO",numFaces:4,outputFaceBlendshapes:true,minFaceDetectionConfidence:.45,minTrackingConfidence:.45};try{landmarker=await FaceLandmarker.createFromOptions(vision,{...options,baseOptions:{...options.baseOptions,delegate:"GPU"}});}catch{landmarker=await FaceLandmarker.createFromOptions(vision,options);}v.pause();setPlaying(false);const step=Math.max(.6,(end-start)/180);const tracks:{centerX:number;score:number;count:number;lastJaw:number;points:FaceTrackPoint[]}[]=[];for(let t=start;t<end;t+=step){v.currentTime=t;await new Promise<void>(resolve=>{if(Math.abs(v.currentTime-t)<.025&&v.readyState>=2)resolve();else v.addEventListener("seeked",()=>resolve(),{once:true});});const result=landmarker.detectForVideo(v,Math.max(1,Math.round(t*1000)));const faces=result.faceLandmarks||[];const blendshapes=result.faceBlendshapes||[];for(let index=0;index<faces.length;index++){const face=faces[index];const xs=face.map((p:any)=>p.x),ys=face.map((p:any)=>p.y);const center={x:Math.max(.05,Math.min(.95,(Math.min(...xs)+Math.max(...xs))/2)),y:Math.max(.05,Math.min(.95,(Math.min(...ys)+Math.max(...ys))/2))};const categories=blendshapes[index]?.categories||[];const jawOpen=categories.find((item:any)=>item.categoryName==="jawOpen")?.score||0;let track=tracks.filter(item=>Math.abs(item.centerX-center.x)<.22).sort((a,b)=>Math.abs(a.centerX-center.x)-Math.abs(b.centerX-center.x))[0];if(!track){track={centerX:center.x,score:0,count:0,lastJaw:jawOpen,points:[]};tracks.push(track);}else{track.score+=Math.abs(jawOpen-track.lastJaw);track.lastJaw=jawOpen;}track.centerX=track.centerX*.55+center.x*.45;track.count++;track.points.push({time:t,x:center.x,y:center.y});}setSceneStatus("Analyzing faces "+Math.round((t-start)/(end-start)*100)+"% · "+faces.length+" visible");}const speakerTrack=tracks.sort((a,b)=>(b.score/Math.max(1,b.count))-(a.score/Math.max(1,a.count)))[0];if(!speakerTrack?.points.length)throw new Error("No faces were detected. Try a video with a clearly visible face.");setFaceTrackPoints(speakerTrack.points);setFitMode("Fill");setSceneStatus("Smart reframe ready · followed the face with the most mouth movement. This is a visual estimate, not audio speaker diarization.");}catch(error){setSceneStatus(error instanceof Error?error.message:"Face tracking failed. Try another video.");}finally{if(landmarker)landmarker.close();v.currentTime=original;setTime(original);setTrackingFaces(false);}};
 const removeLastSplit=()=>{setSplitPoints(p=>p.slice(0,-1));setSelectedSplitIndex(null);};
 const deleteSegment=(side:"before"|"after")=>{if(selectedSplitIndex===null||!splitPoints[selectedSplitIndex])return;const index=selectedSplitIndex;const start=side==="before"?(index===0?trimStart:splitPoints[index-1]):splitPoints[index];const end=side==="before"?splitPoints[index]:(index===splitPoints.length-1?(trimEnd||duration):splitPoints[index+1]);if(end<=start)return;setRemovedRanges(r=>{const sorted=[...r,{start,end}].sort((a,b)=>a.start-b.start);const merged:{start:number;end:number}[]=[];for(const range of sorted){const last=merged[merged.length-1];if(last&&range.start<=last.end+.02)last.end=Math.max(last.end,range.end);else merged.push({...range});}return merged;});}; const resetCuts=()=>{setRemovedRanges([]);setSelectedSplitIndex(null);};
