 const beginBoxDrag=(e:React.PointerEvent<HTMLDivElement>,kind:"facecam"|"game")=>{e.preventDefault();e.stopPropagation();setActive(kind);const box=kind==="facecam"?facecam:game;dragRef.current={kind,mode:"move",startX:e.clientX,startY:e.clientY,originX:box.x,originY:box.y,originW:box.w,originH:box.h};e.currentTarget.setPointerCapture(e.pointerId);};
