 const effectFilters:Record<string,string>={"None":"","Brighten":"brightness(1.22)","Glow":"brightness(1.08) saturate(1.18) drop-shadow(0 0 8px #9bdcff)","Soft Blur":"blur(2px)","Monochrome":"grayscale(1)","Vintage":"sepia(.55) contrast(1.08)","Dreamy":"saturate(1.2) brightness(1.08) blur(.5px)","High Contrast":"contrast(1.35)","Cool Tone":"hue-rotate(12deg) saturate(1.08)","Warm Tone":"sepia(.22) saturate(1.18)","Fade":"contrast(.88) brightness(1.08)","Vivid":"saturate(1.5) contrast(1.08)"}; const previewFilter=[effectFilters[activeEffect],`brightness(${brightness/100})`,`contrast(${contrast/100})`,`saturate(${saturation/100})`].filter(Boolean).join(" ");
 const format=(s:number)=>{const m=Math.floor(s/60);const sec=Math.floor(s%60);const ms=Math.floor((s%1)*30);return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}:${String(ms).padStart(2,"0")}`;};
